import SwiftUI

struct ArticleView: View {
    @EnvironmentObject var dim:DIMENSIONS
    let article:NRPost
    
    init(_ article:NRPost) {
        self.article = article
    }
    
    var body: some View {
        ScrollView {
            VStack {
                Text(article.event.articleTitle ?? "").font(.title)
                if let image = article.event.articleImage {
                    SingleMediaViewer(url: URL(string: image)!, pubkey: article.pubkey, imageWidth: dim.availablePostDetailImageWidth(), isFollowing: true, forceShow: true)
                }
                ContentRenderer(nrPost: article, isDetail: true, fullWidth: false, availableWidth: UIScreen.main.bounds.width)
             
                ArticleCommentsPreview(article: article)
            }
        }
    }
}

struct ArticleCommentsPreview: View {
    let article:NRPost
    var body: some View {
        Text("PFP's here (max 10)")
            .onTapGesture {
                navigateTo(ArticleCommentsPath(article: article))
            }
    }
}

struct ArticleCommentsView: View {
    let article:NRPost
    var body: some View {
        ThreadReplies(nrPost: article)
    }
}

struct ArticleCommentsPath: Identifiable, Hashable {
    var id:String { article.id }
    let article:NRPost
}

struct ArticleView_Previews: PreviewProvider {
